<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, computed } from 'vue'
import type { Slide, Theme } from '@/types/aippt'
import SlideStage from './SlideStage.vue'
const props=defineProps<{slides:Slide[];theme:Theme;start:number}>(),emit=defineEmits<{close:[index:number]}>();const index=ref(props.start),root=ref<HTMLElement|null>(null),controls=ref(true),isFullscreen=ref(false);let timer:ReturnType<typeof setTimeout>|undefined;const current=computed(()=>props.slides[index.value]);const previousFocus=document.activeElement as HTMLElement|null,previousOverflow=document.body.style.overflow
function next(step:number){index.value=Math.max(0,Math.min(props.slides.length-1,index.value+step));showControls()}
function go(value:number){index.value=Math.max(0,Math.min(props.slides.length-1,value));showControls()}
function showControls(){controls.value=true;clearTimeout(timer);timer=setTimeout(()=>controls.value=false,2400)}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await root.value?.requestFullscreen()}catch{controls.value=true}}
async function close(){if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});emit('close',index.value);previousFocus?.focus()}
function fullscreenChanged(){isFullscreen.value=!!document.fullscreenElement}
function key(e:KeyboardEvent){showControls();if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();next(1)}else if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();next(-1)}else if(e.key==='Home'){e.preventDefault();go(0)}else if(e.key==='End'){e.preventDefault();go(props.slides.length-1)}else if(e.key.toLowerCase()==='f'){e.preventDefault();void fullscreen()}else if(e.key==='Escape'){e.preventDefault();if(document.fullscreenElement)void document.exitFullscreen().catch(()=>{});else void close()}}
onMounted(()=>{document.body.style.overflow='hidden';window.addEventListener('keydown',key);document.addEventListener('fullscreenchange',fullscreenChanged);root.value?.focus();showControls()});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);document.removeEventListener('fullscreenchange',fullscreenChanged);clearTimeout(timer);document.body.style.overflow=previousOverflow;if(document.fullscreenElement===root.value)void document.exitFullscreen().catch(()=>{});previousFocus?.focus()})
</script>
<template><Teleport to="body"><div ref="root" class="presentation" role="dialog" aria-modal="true" aria-label="演示文稿放映" tabindex="-1" @mousemove="showControls"><div class="present-slide"><SlideStage v-if="current" :slide="current" :theme="theme" :index="index"/></div><button class="heat previous" aria-label="点击左侧上一页" :disabled="index===0" @click="next(-1)"/><button class="heat next" aria-label="点击右侧下一页" :disabled="index===slides.length-1" @click="next(1)"/><nav v-show="controls" aria-label="放映控制" @click.stop><div class="buttons"><el-button :disabled="index===0" @click="next(-1)">上一页</el-button><span>{{index+1}} / {{slides.length}}</span><el-button :disabled="index===slides.length-1" @click="next(1)">下一页</el-button><el-button @click="fullscreen">{{isFullscreen?'退出全屏（F）':'全屏（F）'}}</el-button><el-button @click="close">退出（Esc）</el-button></div><div class="page-jumps" aria-label="选择放映页"><button v-for="(slide,i) in slides" :key="slide.id" :aria-label="'第'+(i+1)+'页'" :aria-current="index===i?'page':undefined" @click="go(i)">{{i+1}}</button></div></nav></div></Teleport></template>
<style scoped>.presentation{position:fixed;inset:0;background:#151820;z-index:4000;display:grid;place-items:center;outline:none}.present-slide{width:min(100vw,177.777vh)}.heat{position:absolute;inset-block:0;background:transparent;border:0;z-index:1}.heat.previous{left:0;width:28%;cursor:w-resize}.heat.next{right:0;width:72%;cursor:e-resize}.heat:disabled{cursor:default}.heat:focus-visible{outline:2px solid #409eff;outline-offset:-4px}nav{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);max-width:95vw;padding:10px;background:#fff;border-radius:10px;color:#303133;z-index:2}.buttons,.page-jumps{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap}.page-jumps{gap:5px;margin-top:8px}.page-jumps button{border:1px solid #dcdfe6;background:#fff;color:#606266;border-radius:4px;min-width:26px;height:26px;cursor:pointer}.page-jumps [aria-current=page]{background:#409eff;color:#fff}.page-jumps button:focus-visible{outline:2px solid #409eff}</style>
